bool isLog = false;
DateTime startTime = DateTime.Now;
string msg = "开始分解出库任务" + startTime.ToString("yyyy-MM-dd HH:mm:ss:fff");
try
{

	IMainMissionRepository mainMissionRepo = new MainMissionRepository();
	List<MainMissionEntity> mainMissionList = null;
	mainMissionList = mainMissionRepo
		.FindList(x =>
		          x.MissionState == "Create" && (x.task_type == "ST_Out" || x.task_type == "ST_Move"))
		.OrderBy(x => x.CreateTime).ToList();
	//查找完之后进行出库任务分解
	if (mainMissionList.Count > 0)
	{
		isLog = true;
		DBOpeation dbOpeation = new DBOpeation();
		string taskNumbers = string.Join(",", mainMissionList.Select(m => m.task_no));
		msg += $"\r\n\t[出库任务]数量：{mainMissionList.Count},[分解堆垛机任务]处理的任务号：{taskNumbers}";
		var taskResult = dbOpeation.StackerTaskOutCreate(mainMissionList);
		msg += "\r\n\t" + taskResult.Message;
		if(!taskResult.Success)
		{
			Conn.YLLog.Error(1, "[出库任务分解堆垛机任务失败]", 1, taskResult.Message);
		}
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, "[出库任务分解]", 1, ex.ToString());
}
finally
{
	msg += $"\r\n\t[出库任务分解堆垛机任务]End";
	msg += $"\r\n\t[出库任务分解堆垛机任务]耗时：{(int)(DateTime.Now - startTime).TotalMilliseconds}ms";
	if (isLog)
	{
		Conn.YLLog.Info(1, "[出库任务分解堆垛机任务]", 1, msg);
	}
}

