bool isLog = false;
DateTime startTime = DateTime.Now;
string msg = "开始记录:"+startTime.ToString("yyyy-MM-dd HH:mm:ss");
try
{
	DateTime now = DateTime.Now;

	for (int i = 1; i <= 3; i++)
	{
		string suffixName = $"TC0{i}";
		string alarmCode = Conn.YLRedis.GetValue($"{suffixName}.dev_error");
		string memError = Conn.YLRedis.GetValue($"MEM.{suffixName}_Error");
		string taskId = Conn.YLRedis.GetValue($"{suffixName}.dev_taskNo");

		bool hasAlarmChanged = alarmCode != memError;

		if (hasAlarmChanged)
		{
			IDeviceErrorRecordRepository errorRecordRepo = new DeviceErrorRecordRepository();
			IDeviceErrorCodeRepository errorCodeRepo = new DeviceErrorCodeRepository();

			if (alarmCode == "0" || alarmCode == "1")
			{
				DeviceErrorRecordEntity recordToUpdate = null;

				if (!string.IsNullOrEmpty(taskId) && taskId != "0")
				{
					recordToUpdate = errorRecordRepo.FindList(x => x.DeviceTaskNo == taskId).OrderByDescending(x => x.StartTime).FirstOrDefault();
				}
				else
				{
					recordToUpdate = errorRecordRepo.FindList(x => x.DeviceNo == suffixName).OrderByDescending(x => x.StartTime).FirstOrDefault();
				}
				
				if (recordToUpdate != null)
				{
					isLog = true;
					recordToUpdate.EndTime = now;
					recordToUpdate.ErrorState = "OK";
					int dbResult = errorRecordRepo.Update(recordToUpdate);

					if (dbResult > 0)
					{
						msg +=$"\r\n\t记录堆垛机[{suffixName}]报警复位插入数据库成功] {DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
					}
				}

				bool redisResult = Conn.YLRedis.SetValue($"MEM.{suffixName}_Error", alarmCode, "MEMQueue");
				if (!redisResult)
				{
					Conn.YLLog.Error(1, $"{suffixName}记录报警到redis失败", 1, "写入MEM报警代码失败");
				}
			}
			else
			{
				int alarmValue = int.Parse(alarmCode);
				DeviceErrorCodeEntity errorCode = errorCodeRepo.FindEntity(t => t.ErrorCode == alarmValue);

				if (errorCode != null)
				{
					isLog = true;
					DeviceErrorRecordEntity newRecord = new DeviceErrorRecordEntity
					{
						ErrorType = "Device",
						DeviceType = errorCode.DeviceType ?? "Stacker",
						DeviceNo = suffixName,
						DeviceTaskNo = string.IsNullOrEmpty(taskId) || taskId == "0" ? "0" : taskId,
						ErrorCode = alarmCode,
						ErrorDesc = errorCode.ErrorDesc,
						StartTime = now,
						ErrorState = "Error"
					};

					int result = errorRecordRepo.Insert(newRecord);
					if (result >= 1)
					{
						msg +=$"\r\n\t记录堆垛机[{suffixName}]报警[{errorCode.ErrorDesc}]，插入数据库记录成功{DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")}";
						Conn.YLRedis.SetValue($"MEM.{suffixName}_Error", alarmCode, "MEMQueue");
					}
					else
					{
						Conn.YLLog.Error(1, $"{suffixName}堆垛机报警记录失败", 1, $"插入[{errorCode.ErrorDesc}]到数据库失败");
					}
				}
				else
				{
					Conn.YLLog.Error(1, $"{suffixName} 堆垛机报警代码不存在", 1, $"报警代码未正确在数据库表中维护");
				}
			}
		}
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, "堆垛机报警记录异常", 1, ex.ToString());
}
finally
{
	msg += $"\r\n\t[堆垛机报警记录]End";
	msg += $"\r\n\t[堆垛机报警记录]耗时：{(int)(DateTime.Now - startTime).TotalMilliseconds}毫秒";
	if(isLog)
	{
		Conn.YLLog.Info(1, "堆垛机报警记录", 1, msg);
	}
}

