//todo 堆垛机异常处理 放货有货，取货无货 PLC异常反馈1取货无货 2放货有货 3取深浅有 4放深浅有
bool isLog = false;
DateTime startTime = DateTime.Now;
string msg = "开始重分记录" + startTime.ToString("yyyy-MM-dd HH:mm:ss:fff");
try
{
	
	for(int i = 1; i<=3; i++)
	{
		string num = $"0{i}";
		string suffixName = $"TC{num}";
		string stackErrMsg = "";
		string plcBusines = Conn.YLRedis.GetValue($"{suffixName}.dev_taskAbnormalFeedback");
		string confirmSignal = Conn.YLRedis.GetValue($"{suffixName}.wcs_taskErrorAffirm");
		string taskNo = Conn.YLRedis.GetValue($"{suffixName}.dev_taskNo");
		string memDeviceTaskNo = Conn.YLRedis.GetValue($"MEM.{suffixName}_DeviceTaskNo");
		//根据PLC重分信号做对应逻辑处理
		if (confirmSignal == "0" && plcBusines != "0")
		{
			msg += $"\r\n\t获取[suffixName]状态wcs确认异常反馈信号当前值为[{confirmSignal}]，plc的异常反馈信号为[{plcBusines}]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
			switch (plcBusines)
			{
				case "1":
					stackErrMsg = $"[{i}号堆垛机取货无货]"; break;
				case "2":
					stackErrMsg = $"[{i}号堆垛机放货有货]"; break;
				case "3":
					stackErrMsg = $"[{i}号堆垛机取深浅有]"; break;
				case "4":
					stackErrMsg = $"[{i}号堆垛机放深浅有]"; break;
				default:
					stackErrMsg = $"[{i}号堆垛机未知异常]"; break;
			};

			IStackerTaskRepository stackerRepo = new StackerTaskRepository();
			var stackerTaskList = stackerRepo.FindList(t =>t.DeviceTaskNo == taskNo && t.DeviceNo == suffixName).OrderByDescending(t => t.CreateTime).LastOrDefault();
			var mainEntity = new MainMissionRepository().FindList(t => t.device_task_no == taskNo).OrderByDescending(t => t.CreateTime).LastOrDefault();
			//存在任务且重分信号未反馈
			//如果plcBusines==2 或 plcBusines==4，则代表堆垛机放货有货及放伸浅有，需要重分
			if (stackerTaskList != null && mainEntity != null)
			{
				isLog = true;
				StackerSendToRedis stackerSendToRedis = new StackerSendToRedis();
				bool taskRes = false;
				if (plcBusines == "2" || plcBusines == "4")
				{
					//设置重分信号
					taskRes = stackerSendToRedis.ManuTask_SingleStation(plcBusines, num,out string eMsg);
					bool memResend = Conn.YLRedis.SetValue($"MEM.{suffixName}_Resend", "1", "MEMQueue");
					msg += $"\r\n\t{stackerTaskList.TrayCode}{stackErrMsg},写入redis结果{taskRes}，标记重分信号结果{memResend};{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
					if (taskRes && memResend)
					{
						//查堆垛机任务表，找到当前工位的deviceTaskNo
						//更新任务状态
						stackerTaskList.TaskState = "Cancel";
						stackerTaskList.AbnormalFlag = "0";
						stackerTaskList.TaskStartTime = DateTime.Now;
						stackerTaskList.LastUpdatedTime = DateTime.Now;
						var systemSynchronization = new SystemSynchronizationEntity
						{
							syn_direction = 2,
							syn_status = 0,
							ope_type = plcBusines == "2" ? "10" : "12",   // 如果为2放货有货则通知10，如果为4则通知12
							task_no = stackerTaskList.TaskNo,
							tray_code = stackerTaskList.TrayCode,
							order_no = stackerTaskList.DeviceTaskNo,
							road_way = $"{i}",                                 // 几号机就代表几号巷道
							ope_time = DateTime.Now,
							cur_pos = stackerTaskList.ToLocalNo,
							err_cnt = 0
						};

						DBOpeation dbo = new DBOpeation();
						bool result = dbo.UpdateStackInsertSys(stackerTaskList, systemSynchronization, out string eMsg1);
						if (result)
						{
							msg += $"\r\n\t[{suffixName}{stackErrMsg}]，接口插入成功{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
						}
						else
						{
							msg += $"\r\n\t[{stackErrMsg}]，接口信息插入失败";
						}
					}
				}
				//plcBusines==1 或 plcBusines==3，则代表堆垛机取货无货
				if (plcBusines == "1" || plcBusines == "3")
				{
					taskRes = stackerSendToRedis.ManuTask_SingleStation(plcBusines,num,out string eMsg3);
					bool redisRes = stackerSendToRedis.StackMemTaskInfo("0", "0", "0", "0",num);
					msg += $"\r\n\t{stackerTaskList.TrayCode}{stackErrMsg},写入redis结果{taskRes};{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
					if(taskRes && redisRes)
					{
						// 更新任务状态
						stackerTaskList.TaskState = "Cancel";
						stackerTaskList.TaskStartTime = DateTime.Now;
						stackerTaskList.LastUpdatedTime = DateTime.Now;
						
						mainEntity.MissionState = "Cancel";
						mainEntity.MissionEndTime = DateTime.Now;
						mainEntity.LastUpdatedTime = DateTime.Now;
						
						//向wms通知9取货无货 11取深浅有
						var systemSynchronization = new SystemSynchronizationEntity
						{
							syn_direction = 2,                             // 取消任务
							syn_status = 0,
							ope_type = plcBusines == "1" ? "9" : "11",    // 1→9，其他→11
							task_no = stackerTaskList.TaskNo,
							tray_code = stackerTaskList.TrayCode,
							order_no = stackerTaskList.DeviceTaskNo,
							road_way = $"{i}",
							cur_pos = stackerTaskList.FromLocalNo,
							ope_time = DateTime.Now,
							err_cnt = 0
						};

						DBOpeation dbo = new DBOpeation();
						bool result = dbo.UpdateMainAndStackInsertSysTask(mainEntity, stackerTaskList,
						                                                  systemSynchronization, out string dbMsg);
						if(result)
						{
							msg += $"\r\n\t{stackerTaskList.TrayCode}{stackErrMsg},上报wms取消任务，取消主任务和堆垛机任务;{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
						}
						else
						{
							msg += $"\r\n\t{stackerTaskList.TrayCode}{stackErrMsg},任务和接口插入失败{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
						}
					}

				}
				else
				{
					msg += $"\r\n\t[{suffixName}堆垛机异常{stackErrMsg}]错误, 未查询到[{taskNo}的堆垛机任务]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
					Conn.YLLog.Error(1, "任务重分处理异常", 1, msg);
				}
			}
			else
			{
				//重分信号已反馈
				msg += $"\r\n\t[{suffixName}堆垛机异常{stackErrMsg}]，当前状态为[{plcBusines}],当前plc的任务号为{taskNo}{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}]";
			}
		}
		//置位WCS重分信号
		if(confirmSignal != "0" &&  plcBusines == "0")
		{
			isLog = true;
			StackerSendToRedis stackerSendToRedis = new StackerSendToRedis();
			bool res = stackerSendToRedis.ManuTask_SingleStation("0",num,out string err);
			if(res)
			{
				msg += $"\r\n\t[{suffixName}堆垛机重分信号已置位{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}]";
			}
		}
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, "堆垛机报警等待重分任务处理异常", 1, ex.Message);
}
finally
{
	msg += $"\r\n\t[堆垛机异常任务处理]End";
	msg += $"\r\n\t[堆垛机异常任务处理]耗时：{(int)(DateTime.Now - startTime).TotalMilliseconds}毫秒";
	if(isLog)
	{
		Conn.YLLog.Info(1, "堆垛机报警等待重分任务处理", 1, msg);
	}
}

