//任务重分处理
bool isLog = false;
DateTime startTime = DateTime.Now;
string msg = "任务重分堆垛机下发" + startTime.ToString("yyyy-MM-dd HH:mm:ss:fff");
try
{
	for(int i = 1; i<=3; i++)
	{
		string num = $"0{i}";
		string suffixName = $"TC{num}";
		string memResend = Conn.YLRedis.GetValue($"MEM.{suffixName}_Resend");
		string modeValue = Conn.YLRedis.GetValue($"{suffixName}.dev_pattern"); // 设备模式 1联机自动; 2手动; 3离线; 4维修;
		string faultValue = Conn.YLRedis.GetValue($"{suffixName}.dev_error"); // 报警 0正常
		string stateValue = Conn.YLRedis.GetValue($"{suffixName}.dev_dispatch"); // 1正常 允许下发任务
		string loadedValue = Conn.YLRedis.GetValue($"{suffixName}.dev_load");//载货台有无货物 1有货 0 无货
		if (memResend == "1")
		{
			isLog = true;
			msg += $"\r\n\t获取[{suffixName}]状态当前值为[{memResend}]，开始进行重分处理";
			// 查询设备的任务号
			//string deviceTaskNo = Conn.YLRedis.GetValue($"{suffixName}.dev_taskNo");
			string memDeviceTaskNo = Conn.YLRedis.GetValue($"MEM.{suffixName}_DeviceTaskNo");
			if(memDeviceTaskNo == "0")
			{
				//设置重分信号置位
				bool res = Conn.YLRedis.SetValue($"MEM.{suffixName}_Resend", "0", "MEMQueue");
				msg += $"\r\n\t[{suffixName}]堆垛机任务已取消，无法查询当前任务号，置位重分信号{memDeviceTaskNo}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
				continue;
			}
			IStackerTaskRepository stackerRepo = new StackerTaskRepository();
			var stackerTaskList = stackerRepo.FindList(t => (t.TaskState == "Cancel") && t.DeviceTaskNo == memDeviceTaskNo
			                                           && t.DeviceNo == suffixName && t.AbnormalFlag == "1").OrderByDescending(t => t.CreateTime).FirstOrDefault();
			if (stackerTaskList != null )
			{
				if (modeValue == "1" && stateValue == "1" && faultValue == "0")
				{
					//载货台有货，可以正常重分
					if(loadedValue == "1")
					{
						DBOpeation dbOpeation = new DBOpeation();
						stackerTaskList.AbnormalFlag = "0";//重分成功置位一下
						stackerTaskList.TaskState = "Send";
						stackerTaskList.TaskStartTime = DateTime.Now;
						stackerTaskList.LastUpdatedTime = DateTime.Now;
						bool dbResult = dbOpeation.UpdateStackerTask(stackerTaskList, out string errorMsg);
						msg += $"\r\n\t[suffixName]重分更新任务信息结束，写入结果：{(dbResult ? "成功" : "失败")}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}" + errorMsg;
						if (dbResult)
						{
							StackerSendToRedis stackerSendToRedis = new StackerSendToRedis();
							bool result = stackerSendToRedis.SendTask_SingleStation(stackerTaskList,num, out string eMsg);
							//更新任务
							msg += $"\r\n\t[suffixName]堆垛机重分信号下发写入结果：{(result ? "成功" : "失败")}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
							if (result)
							{
								bool memResult = stackerSendToRedis.StackMemTaskInfo(stackerTaskList.DeviceTaskNo, stackerTaskList.TrayCode, stackerTaskList.FromLocalNo, stackerTaskList.ToLocalNo, num);
								//设置重分信号置位
								bool res = Conn.YLRedis.SetValue($"MEM.{suffixName}_Resend", "0", "MEMQueue");
								msg +=
									$"\r\n\t[suffixName]标记重分复位，重分的任务信息写入结果{memResult}，已将任务重分给堆垛机，置位重分信号写入结果：{(res ? "成功" : "失败")}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
								if(!memResult || !res)
								{
									msg += $"\r\n\t[suffixName]写入到redis信号写入失败，请检查{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
									Conn.YLLog.Error(1, "堆垛机标记重分处理异常", 1, msg);
								}
							}
							else
							{
								msg += $"\r\n\t[suffixName]堆垛机重分，工位任务信号发送堆垛机失败{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
							}
						}
						else
						{
							msg += $"\r\n\t[suffixName]堆垛机重分，工位任务更新数据库失败{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
						}
					}
					else
					{
						//载货台货物状态异常，设置重分信号置位
						bool res = Conn.YLRedis.SetValue($"MEM.{suffixName}_Resend", "0", "MEMQueue");
						msg += $"\r\n\t[suffixName]载货台无货，标记重分复位，重分的任务信息写入结果{res}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
					}
				}
				else
				{
					msg += $"\r\n\t[{suffixName}]堆垛机重分信号下发失败，设备模式[{modeValue}]，设备状态[{stateValue}]，载货台货物[{loadedValue}]{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
				}
			}
			else
