				msg += $"\r\n\t[{suffixName}]堆垛机重分，未查询到相关任务，等待wms分配货位结果{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
			}
		}
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, "堆垛机标记重分处理", 1, ex.Message);
}
finally
{
	msg += $"\r\n\t[堆垛机标记重分处理]End";
	msg += $"\r\n\t[堆垛机标记重分处理]耗时：{(int)(DateTime.Now - startTime).TotalMilliseconds}毫秒";
	if(isLog)
	{
		Conn.YLLog.Info(1, "堆垛机标记重分处理", 1, msg);
	}
}

