							//更新任务
							msg += $"\r\n\t[suffixName]堆垛机重分信号下发写入结果：{(result ? "成功" : "失败")}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
							if (result)
							{
								bool memResult = stackerSendToRedis.StackMemTaskInfo(stackerTaskList.DeviceTaskNo, stackerTaskList.TrayCode, stackerTaskList.FromLocalNo, stackerTaskList.ToLocalNo, num);
								//设置重分信号置位
								bool res = Conn.YLRedis.SetValue($"MEM.{suffixName}_Resend", "0", "MEMQueue");
								msg +=
									$"\r\n\t[suffixName]标记重分复位，重分的任务信息写入结果{memResult}，已将任务重分给堆垛机，置位重分信号写入结果：{(res ? "成功" : "失败")}{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
								if(!memResult || !res)
								{
									msg += $"\r\n\t[suffixName]写入到redis信号写入失败，请检查{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
