//堆垛机取货完成信号上报wms
bool isLog = false;
DateTime startTime = DateTime.Now;
string msg = "取货完成上报" + startTime.ToString("yyyy-MM-dd HH:mm:ss:fff");
try
{
	for(int i = 1; i<=3; i++)
	{
		string num = $"0{i}";
		string suffixName = $"TC{num}";
		string devClaimGood = Conn.YLRedis.GetValue($"{suffixName}.dev_claimGoods");
		string wcsClaimGood = Conn.YLRedis.GetValue($"{suffixName}.wcs_taskInAffirm");
		//string load = Conn.YLRedis.GetValue($"{suffixName}.dev_load");//载货台有无货物 1有货 0 无货
		string taskNo = Conn.YLRedis.GetValue($"{suffixName}.dev_taskNo");
		bool claimResult = false;
		//根据PLC取货完成信号做对应逻辑处理
		if (wcsClaimGood == "0" && devClaimGood == "1")
		{
			msg += $"\r\n\t获取[{suffixName}]取货完成信号，WCS当前值为[{wcsClaimGood}]，PLC当前值为[{devClaimGood}]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
			StackerSendToRedis stackerSendToRedis = new StackerSendToRedis();
			IStackerTaskRepository stackerRepo = new StackerTaskRepository();
			var stackerTask = stackerRepo.FindList(t => t.DeviceTaskNo == taskNo && t.DeviceNo == suffixName).OrderByDescending(t => t.CreateTime).LastOrDefault();
			if (stackerTask != null )
			{
				isLog = true;
				claimResult = stackerSendToRedis.DeliveryTask_SingleStation("1",num,out string err);
				//上报wms取货完成
				var systemSynchronization = new SystemSynchronizationEntity
				{
					syn_direction = 2,
					syn_status = 0,
					ope_type = "4",   // 堆垛机取货完成
					task_no = stackerTask.TaskNo,
					order_no = stackerTask.DeviceTaskNo,
					tray_code = stackerTask.TrayCode,
					ope_time = DateTime.Now,
					cur_pos = stackerTask.FromLocalNo,
					err_cnt = 0
				};

				stackerTask.LastUpdatedTime = DateTime.Now;
				DBOpeation dbo = new DBOpeation();
				bool result = dbo.UpdateStackInsertSys(stackerTask,systemSynchronization, out string dbMsg);
				if(result)
				{
					msg += $"\r\n\t托盘号{stackerTask.TrayCode}，任务号为{stackerTask.TaskNo}，上报wms取货完成信号成功;{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
				}
				else
				{
					msg += $"\r\n\t[{stackerTask.TaskNo}]的条码[{stackerTask.TrayCode}]接口插入失败{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
				}
			}
			else
			{
				claimResult = stackerSendToRedis.DeliveryTask_SingleStation("1",num,out string err);
				msg += $"\r\n\t[{suffixName}堆垛机取货完成异常, 未查询到[{taskNo}的堆垛机任务]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
				Conn.YLLog.Error(1, "堆垛机任务取货完成处理异常", 1, msg);
			}
		}

		//置位WCS取货完成
		else if(wcsClaimGood == "1" &&  devClaimGood == "0")
		{
			//isLog = true;
			StackerSendToRedis stackerSendToRedis = new StackerSendToRedis();
			claimResult = stackerSendToRedis.DeliveryTask_SingleStation("0",num,out string err);
			if(claimResult)
			{
				msg += $"\r\n\t[{suffixName}堆垛机取货完成信号已置位{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}]";
			}
		}
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, "取货完成处理异常", 1, ex.Message);
}
finally
{
	msg += $"\r\n\t[堆垛机取货完成处理]End";
	msg += $"\r\n\t[堆垛机取货完成处理]耗时：{(int)(DateTime.Now - startTime).TotalMilliseconds}毫秒";
	if(isLog)
	{
		Conn.YLLog.Info(1, "堆垛机取货完成处理", 1, msg);
	}
}

