//一号机任务反馈判断  1自动完成 2强制完成 3手动取消

//后续考虑除了任务下发，把所有信号反馈全部封装到一个包里面
DateTime startTime = DateTime.Now;
string num = "01";
string msg = $"\r\n\t[{num}号]堆垛机任务信号反馈：Start{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
TaskConfirmResult helperResult = null;
bool isLog = false;
try
{
	string suffixName = $"TC{num}";
	string wcsConfirmSignal = Conn.YLRedis.GetValue($"{suffixName}.wcs_taskFinishAffirm");
	string plcTaskStatus = Conn.YLRedis.GetValue($"{suffixName}.dev_taskFinishState");
	msg +=
		$"\r\n\t获取wcs的确认信号[{wcsConfirmSignal}]，plc状态当前值为[{plcTaskStatus}]]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss")}";
	//逻辑处理
	if (wcsConfirmSignal != "0" && plcTaskStatus == "0")
	{
		var taskConfirmHelper = new TaskConfirmHelper();
		helperResult = taskConfirmHelper.InteractionFeedback(num);
		isLog = true;
	}
	//交互
	else if (wcsConfirmSignal == "0" && plcTaskStatus != "0")
	{
		isLog = true;
		var taskConfirmHelper = new TaskConfirmHelper();
		switch (plcTaskStatus)
		{
			case "1": //1正常完成
				helperResult = taskConfirmHelper.NormalFinishFeedback(num);
				break;
			case "2": //2强制完成
				helperResult = taskConfirmHelper.ForceFinishFeedback(num);
				break;
			case "3": //3取消
				helperResult = taskConfirmHelper.CancelFeedback(num);
				break;
		}
	}
	else
	{
		msg += $"\r\n\t[{suffixName}堆垛机任务完成反馈信号未满足要求]End";
	}

	// 统一处理返回的结果
	if (helperResult != null)
	{
		msg += helperResult.Message;
	}
}
catch (Exception ex)
{
	Conn.YLLog.Error(1, $"{num}号机任务反馈异常", 1, ex.ToString());
}
finally
{
	msg += $"\r\n\t[{num}号机任务反馈]End{DateTime.Now:yyyy/MM/dd HH:mm:ss:fff}";
	msg += $"\r\n\t[{num}号机任务反馈]耗时：{(DateTime.Now - startTime).TotalMilliseconds}ms";

	// 统一输出日志
	if (isLog)
	{
		if (helperResult.IsSuccess)
		{
			Conn.YLLog.Info(1, $"{num}号机任务反馈处理完成", 1, msg);
		}
		else
		{
			Conn.YLLog.Error(1, $"{num}号机任务反馈处理失败", 1, msg);
		}
	}
}

