var startTime = DateTime.Now;
string msg = $"[StartTime]{startTime:yyyy-MM-dd HH:mm:ss:fff}";
var reqListFloor = new List<string>{"1002", "1006", "1008"};
//前置变量
bool dbResult = false;
bool result = false;
bool memResult = false;
bool isLog = false;

foreach (var station in reqListFloor)
{
	string deviceNo = RouteHelper.GetDeviceNo(station, "CV");
	try
	{
		string plcReq = Conn.YLRedis.GetValue($"{deviceNo}.plc_toReq_{station}");
		string wcsSent = Conn.YLRedis.GetValue($"{deviceNo}.wcs_stb_{station}");
		string memReq = Conn.YLRedis.GetValue($"MEM.plc_toReq_{station}");
		// 读取输送线的条码、外形和重量信息
		string contNo = Conn.YLRedis.GetValue($"{deviceNo}.plc_contNo_{station}");
		string shape = Conn.YLRedis.GetValue($"{deviceNo}.plc_shape_{station}");
		string weight = Conn.YLRedis.GetValue($"{deviceNo}.plc_weight_{station}");

		// 触发条件：到位请求为 '1' 且  WCS未发送指令
		if (plcReq == "1"  && wcsSent == "0" && memReq == "0")
		{
			isLog = true;
			IMainMissionRepository mainRepo = new MainMissionRepository();
			// 1️ 优先查找托盘号对应的任务
			var mainMission = mainRepo
				.FindList(t => t.tray_code == contNo && t.InteStationNo == station && t.task_type == "ST_In" && t.MissionState == "Create")
				.OrderByDescending(t => t.CreateTime)
				.FirstOrDefault();

			// 2️ 如果找不到托盘号对应的任务，则取该站最新一条任务
			if (mainMission == null)
			{
				mainMission = mainRepo
					.FindList(t => t.InteStationNo == station && t.task_type == "ST_In" && t.MissionState == "Create")
					.OrderByDescending(t => t.CreateTime)
					.FirstOrDefault();
			}
			if(mainMission != null)
			{
				msg += $"\r\n\t[{station}读码申请去向]该站台获取任务成功，获取其他信息weight:{weight},shape:{shape},contNo:{contNo} {DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
				
				if (int.Parse(weight) > 1000 || int.Parse(weight) <= 0 || mainMission.tray_code != contNo)
				{
					string returnMsg = "";
					string taskType = "";
					if (contNo.ToUpper() == "NOREAD")
					{
						returnMsg = $"设备未读码成功，读取条码为：NOREAD";
						taskType = "6";
					}
					else if (mainMission.tray_code != contNo)
					{
						returnMsg = $"托盘条码与任务条码不符，任务托盘码为[{mainMission.tray_code}]，设备读取托盘码为[{contNo}]";
						taskType = "7";
					}
					else if (int.Parse(weight) > 1000)
					{
						returnMsg = $"超重，重量信息为：{weight}";
						taskType = "5";
					}
					else if (int.Parse(weight) <= 0)
					{
						returnMsg = $"重量异常，重量信息为：{weight}";
						taskType = "5";
					}
					else if (shape != "0")
					{
						string desc = GetShapeDesc(shape);
						returnMsg = $"外检失败：{desc}";
						taskType = "4";
					}
					
					string flow = RouteHelper.GetNextStn(station, "BACK");
					
					mainMission.MissionState = "Error";
					mainMission.LastUpdatedTime = DateTime.Now;
					mainMission.InteStationNo = flow;
					mainMission.reverse_5 = $"{returnMsg} ";
					
					//执行数据库操作
					DBOpeation dbOpeation = new DBOpeation();
					dbResult = dbOpeation.UpdateMainTask(mainMission,out string eMsg);
					msg += $"\r\n\t[数据库操作] 操作结果：{(dbResult ? "成功" : "失败")} - {eMsg}";
					if (dbResult)
					{
						//数据库执行成功执行Redis写入操作
						ConveyorSendToRedis conveyorSendToRedis = new ConveyorSendToRedis();
						result = conveyorSendToRedis.SendTask_Station(deviceNo, station, mainMission.device_task_no, flow, taskType,"1", out string err);
						msg += $"\r\n\t[redis写入]写入redis点位信息结束，写入结果：{result} - {err} {DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
						if(result)
						{
							memResult = Conn.YLRedis.SetValue($"MEM.plc_toReq_{station}", plcReq, "MEMQueue");
							msg += $"\r\n\t[MEM写入]记录MEM信息结束，写入结果：{memResult}{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
						}
					}
					else
					{
						Conn.YLLog.Error(1, $"[入库站台[{station}]数据库操作失败", 1, eMsg);
					}
				}
				else
				{
					string flow = RouteHelper.GetNextStn(station, "FORWARD");
					mainMission.MissionState = "Doing";
					mainMission.InteStationNo = flow;
					mainMission.LastUpdatedTime = DateTime.Now;
					mainMission.reverse_5 = $"weight:{weight},shape:{shape},contNo:{contNo} 匹配入库";
					
					//执行数据库操作
					DBOpeation dbOpeation = new DBOpeation();
					dbResult = dbOpeation.UpdateMainTask(mainMission,out string eMsg);
					msg += $"\r\n\t[数据库操作] 操作结果：{(dbResult ? "成功" : "失败")} - {eMsg}";
					if (dbResult)
					{
						//数据库执行成功执行Redis写入操作
						ConveyorSendToRedis conveyorSendToRedis = new ConveyorSendToRedis();
						result = conveyorSendToRedis.SendTask_Station(deviceNo, station, mainMission.device_task_no, flow, "1","1", out string err);
						msg += $"\r\n\t[redis写入]写入redis点位信息结束，写入结果：{result} - {err} {DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
						if(result)
						{
							memResult = Conn.YLRedis.SetValue($"MEM.plc_toReq_{station}", plcReq, "MEMQueue");
							msg += $"\r\n\t[MEM写入]记录MEM信息结束，写入结果：{memResult}{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
						}
					}
					else
					{
						Conn.YLLog.Error(1, $"[入库站台[{station}]数据库操作失败", 1, eMsg);
					}
				}
			}
			else
			{
				msg += $"\r\n\t[{station}读码]未检测到wms相关任务 {DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
			}
		}
	}
	catch (Exception ex)
	{
		Conn.YLLog.Error(1, $"[{station}]去向请求1处理异常", 1, msg + ex);
	}
	finally
	{
		msg += "\r\n\t[EndTime]" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss:fff");
		msg += "\r\n\t[SpanTime]" + (int)(DateTime.Now - startTime).TotalMilliseconds + "ms";
		if(isLog)
		{
			Conn.YLLog.Info(1, $"[{station}]站台去向请求1", 1, msg);
		}
	}
}

