						                StackerTaskEntity stacker = (obj as DataGrid).SelectedItem as StackerTaskEntity;
                if (stacker == null)
                {
                    MessageBox.Show("请选择要取消的任务");
                    return;
                }
                SystemSynchronizationEntity sys = null;
                MainMissionEntity pcmMain = null;
                Certification window = new Certification();
                if (window.ShowDialog() == true)
                {
                    if (stacker != null)
                    {
                        string str = stacker.DeviceNo;
                        int num = str[(str.Length - 1)];
                        string dispatch = Conn.YLRedis.GetValue($"PLC_Stacker{num}.dev_dispatch");
                        if (dispatch == "1")
                        {
                            stacker.TaskState = OrderStates.Finish;
                            stacker.AbnormalFlag = "1";
                            stacker.AbnormalDesc = "强制完成" + DateTime.Now;

                            using (var context = new NFineDbContext())
                            {
                                pcmMain = context.Set<MainMissionEntity>().FirstOrDefault(x => x.task_no == stacker.TaskNo && x.order_no == stacker.OrderNo);
                            }
                            if (pcmMain != null)
                            {
                                if (stacker.TaskType == OrderTypes.MT_In || stacker.TaskType == OrderTypes.KTP_In || (stacker.TaskType == OrderTypes.DT_Move && !stacker.ToLocalNo.StartsWith("KQ_ReleaseStation")))
                                {

                                    pcmMain.MissionState = "Finish";
                                    pcmMain.MissionEndTime = DateTime.Now;
                                    pcmMain.LastUpdatedTime = DateTime.Now;
                                    pcmMain.InteStationNo = stacker.ToLocalNo;
                                    #region 写入同步表
                                    sys = new SystemSynchronizationEntity();
                                    sys.syn_direction = 1;
                                    sys.syn_status = 0;
                                    sys.ope_type = TaskFlow.Task_CF;
                                    sys.task_type = pcmMain.task_type;
                                    sys.order_no = pcmMain.order_no;
                                    sys.task_no = pcmMain.task_no;
                                    sys.ope_time = DateTime.Now;
                                    sys.reverse_1 = pcmMain.tray_code;
                                    #endregion

                                }
                                if (stacker.TaskType == OrderTypes.MT_Out || stacker.TaskType == OrderTypes.KTP_Out || stacker.TaskType == OrderTypes.InOt_Move || (stacker.TaskType == OrderTypes.DT_Move && stacker.ToLocalNo.StartsWith("KQ_ReleaseStation")))

                                {
                                    pcmMain.InteStationNo = stacker.ToLocalNo;
                                    string[] ToLocalNo = stacker.ToLocalNo.Split('_');
                                    string strProNode = "";
                                    if (ToLocalNo[0] == "KQ" || ToLocalNo[0] == "KR")
                                    {
                                        strProNode = $"F1R.OtSt{num}";
                                    }
                                    else if (ToLocalNo[0] == "KL")
                                    {
                                        strProNode = $"F1L_OtSt{num}";
                                    }
                                    else
                                    {
                                        strProNode = $"{ToLocalNo[0]}_OtSt{num}";
                                    }
                                    //#region 写入同步表
                                    sys = new SystemSynchronizationEntity
                                    {
                                        syn_direction = 1,
                                        syn_status = 0,
                                        ope_type = TaskFlow.Task_ProNode,
                                        task_type = pcmMain.task_type,
                                        order_no = pcmMain.order_no,
                                        task_no = pcmMain.task_no,
                                        reverse_1 = pcmMain.tray_code,
                                        reverse_2 = strProNode,
                                        ope_time = DateTime.Now
                                    };
                                }
                            }
                        }

                    }
                    LogEntity logEntity = new LogEntity(); ;
                    logEntity.LogType = "2";
                    logEntity.ProType = "堆垛机任务管理";
                    logEntity.OpeType = "2";
                    logEntity.OpeTime = DateTime.Now;
                    logEntity.OpeUser = Tag.UI.登录.登录人;
                    logEntity.CreateTime = DateTime.Now;
                    logEntity.LogContent = $"强制完成堆垛机任务号为{stacker.TaskNo}，卡号为：{stacker.TrayCode}，库位为：{stacker.ToLocalNo},成功";
                    using (var context = new NFineDbContext())
                    {
                        using (var transaction = context.Database.BeginTransaction())
                        {
                            if (stacker != null)
                            {
                                context.Set<StackerTaskEntity>().Attach(stacker);
                                context.Entry(stacker).State = EntityState.Modified;
                            }
                            if (pcmMain != null)
                            {
                                context.Set<MainMissionEntity>().Attach(pcmMain);
                                context.Entry(pcmMain).State = EntityState.Modified;
                            }
                            if (sys != null)
                            {
                                context.Set<SystemSynchronizationEntity>().Add(sys);
                            }
                            if (logEntity != null)
                            {
                                context.Set<LogEntity>().Add(logEntity);
                            }
                            context.SaveChanges();
                            transaction.Commit();
                        }
                    }
                    Get_List_StackerTask("First");
                }
                else
                {
                    MessageBox.Show("未找到对应任务，请重新查询后操作");
                    return;
                }

