	if (string.IsNullOrEmpty(Tag.用户权限.TXT_PassWord) || string.IsNullOrEmpty(Tag.用户权限.TXT_Name))
	{
		MessageBox.Show("用户、密码 等不能为空！！！");
		return;
	}
	using (var context = new NFineDbContext())
	{
		if (Tag.用户权限.TXT_Total == "修改用户信息")
