			}
		}

		else if (Tag.用户权限.TXT_Total == "新增用户信息")
		{
			DictEntity user = new DictEntity
			{
				DictType = "用户信息",
				DictName = Tag.用户权限.TXT_Name,
				DictValue = Tag.用户权限.TXT_PassWord,
				DictStr = Tag.用户权限.Bool_Button ? "是" : "否",
			};


			DictEntity account = context.Set<DictEntity>().Where(x => x.DictType == "用户信息" && x.DictName == Tag.用户权限.TXT_Name).FirstOrDefault();
			if (account != null)
			{
				MessageBox.Show("用户已存在！！！");
				return;
			}

			context.Set<DictEntity>().Add(user);
			MessageBox.Show("添加成功！！！");

		}
		context.SaveChanges();

	}
	Window win = multiObj[0] as Window;
	win.Close();
	GetUserPermissions("First");
}
catch (Exception)
{

	MessageBox.Show("保存失败", "提示", MessageBoxButton.OK, MessageBoxImage.Error);
}

