IDeviceErrorRecordRepository DeviceErrorRecordServer = new DeviceErrorRecordRepository();

var expression = ExtLinq.True<DeviceErrorRecordEntity>();
//设备任务号
if (!string.IsNullOrEmpty(Tag.堆垛机报警.TXT_DeviceTaskNo))
{
	expression = expression.And(t => t.DeviceTaskNo.Contains(Tag.堆垛机报警.TXT_DeviceTaskNo));
}
//设备编号
if (!string.IsNullOrEmpty(Tag.堆垛机报警.TXT_DeviceNo))
{
	expression = expression.And(t => t.DeviceNo == Tag.堆垛机报警.TXT_DeviceNo);
}
//报警起始时间
if (!string.IsNullOrEmpty(Tag.堆垛机报警.TXT_StartTime))
{
	DateTime str_CreateTime = Convert.ToDateTime(Convert.ToDateTime(Tag.堆垛机报警.TXT_StartTime).ToString("yyyy-MM-dd"));
	expression = expression.And(t => t.StartTime >= str_CreateTime);
}
//报警结束时间
if (!string.IsNullOrEmpty(Tag.堆垛机报警.TXT_EndTime))
{
	DateTime str_EndTime = Convert.ToDateTime(Convert.ToDateTime(Tag.堆垛机报警.TXT_EndTime).AddDays(1).ToString("yyyy-MM-dd"));
	expression = expression.And(t => t.EndTime <= str_EndTime);
}
expression = expression.And(t => t.DeviceType == "Stacker");


List<DeviceErrorRecordEntity> mains = DeviceErrorRecordServer.FindList(expression);
List<DeviceErrorRecordEntity> mainsList =new List<DeviceErrorRecordEntity>();
